/**
 * TASK: Complete the immutable ImmutableAccount class.
 *
 * The fields are final -- an account can never change. "Modifying"
 * methods therefore return a NEW account instead:
 *
 *   ImmutableAccount a = new ImmutableAccount("Ana", 100.0);
 *   ImmutableAccount b = a.withDeposit(50.0);
 *   b.getBalance() -> 150.0     a.getBalance() -> still 100.0
 *
 *   ImmutableAccount c = a.withOwner("Ben");
 *   c.getOwner() -> "Ben"       c.getBalance() -> 100.0
 */
public class ImmutableAccount {

    private final String owner;
    private final double balance;

    public ImmutableAccount(String owner, double balance) {
        this.owner = owner;
        this.balance = balance;
    }

    public String getOwner() {
        return owner;
    }

    public double getBalance() {
        return balance;
    }

    public ImmutableAccount withDeposit(double amount) {
        // TODO: return a NEW account with the same owner and a raised balance
        return null;
    }

    public ImmutableAccount withOwner(String newOwner) {
        // TODO: return a NEW account with the new owner and the same balance
        return null;
    }
}

