public class ImmutableAccountTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ImmutableAccount a = new ImmutableAccount("Ana", 100.0);
        check("owner stored", "Ana", a.getOwner());
        check("balance stored", 100.0, a.getBalance());

        ImmutableAccount b = a.withDeposit(50.0);
        check("deposit result has new balance", 150.0, b == null ? null : b.getBalance());
        check("deposit result keeps owner", "Ana", b == null ? null : b.getOwner());
        check("original balance unchanged", 100.0, a.getBalance());

        ImmutableAccount c = a.withOwner("Ben");
        check("withOwner result has new owner", "Ben", c == null ? null : c.getOwner());
        check("withOwner result keeps balance", 100.0, c == null ? null : c.getBalance());
        check("original owner unchanged", "Ana", a.getOwner());

        Object chained;
        try {
            ImmutableAccount d = a.withDeposit(25.0).withDeposit(25.0);
            chained = d == null ? null : d.getBalance();
        } catch (RuntimeException e) {
            chained = "exception";
        }
        check("chained deposits build on each new object", 150.0, chained);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

