public class ImmutableAccount {

    private final String owner;
    private final double balance;

    public ImmutableAccount(String owner, double balance) {
        this.owner = owner;
        this.balance = balance;
    }

    public String getOwner() {
        return owner;
    }

    public double getBalance() {
        return balance;
    }

    public ImmutableAccount withDeposit(double amount) {
        return new ImmutableAccount(owner, balance + amount);
    }

    public ImmutableAccount withOwner(String newOwner) {
        return new ImmutableAccount(newOwner, balance);
    }
}
